        Exercise(id: "builtin.plank-leg-lift", name: "平板支撑交替抬腿", englishName: "Plank with Alternating Leg Lift", kind: .bodyweight, metric: .duration, equipment: "平整地面", muscle: "核心", loadConvention: .bodyweight, instructions: ["以前臂和脚尖建立平板支撑，骨盆保持朝地，交替小幅抬起一侧直腿。", "抬腿时臀部发力但不反弓腰部，将脚尖受控放回后再换侧。", "姿势开始失控前结束，不以塌腰换取时间。"]),
        Exercise(id: "builtin.pallof-press", name: "绳索帕洛夫推", englishName: "Pallof Press", kind: .strength, metric: .repetitions, equipment: "绳索器械、单把手", muscle: "腹斜肌", loadConvention: .total, instructions: ["侧对胸部高度的绳索，双脚站稳，双手持把手。", "保持胸廓与骨盆朝前，将双手缓慢推离胸部。", "受控拉回胸前后换侧，不让负重把身体扭转。"]),
