    static let sources: [String: ExerciseContentSource] = [
        "builtin.decline-barbell-press": ExerciseContentSource(title: "Decline Bench Press Barbell", url: "https://wger.de/api/v2/exerciseinfo/185/", author: "wger.de", licenseName: "CC-BY-SA 3", licenseURL: "https://creativecommons.org/licenses/by-sa/3.0/deed.en", originalDescription: "Lay down on a decline bench, the bar should be directly above your eyes, the knees are somewhat angled and the feet are firmly on the floor. Concentrate, breath deeply and grab the bar more than shoulder wide. Bring it slowly down till it briefly touches your chest at the height of your nipples. Push the bar up."),
        "builtin.decline-dumbbell-press": ExerciseContentSource(title: "Decline Bench Press Dumbbell", url: "https://wger.de/api/v2/exerciseinfo/186/", author: "wger.de", licenseName: "CC-BY-SA 3", licenseURL: "https://creativecommons.org/licenses/by-sa/3.0/deed.en", originalDescription: "Take two dumbbells and sit on a decline bench, the feet are firmly on the floor, the head is resting the bench. Hold the weights next to the chest, at the height of your nipples and press them up till the arms are stretched. Let the weight slowly and controlled down."),
        "builtin.smith-incline-press": ExerciseContentSource(title: "Incline Bench Press - MP", url: "https://wger.de/api/v2/exerciseinfo/539/", author: "wger.de", licenseName: "CC-BY-SA 3", licenseURL: "https://creativecommons.org/licenses/by-sa/3.0/deed.en", originalDescription: ""),
        "builtin.dumbbell-floor-press": ExerciseContentSource(title: "Dumbbell Floor Press", url: "https://wger.de/api/v2/exerciseinfo/1084/", author: "admin", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "Grab your dumbbells and lay flat on your back with your knees bent and your feet flat on the ground (use a bench if you have one). Press the weights up, locking out your elbows (A). Lower them slowly until your upper arms are resting on the floor (B) close to your body. Pause here before explosively pressing back up. Squeeze your chest hard and repeat."),
        "builtin.dumbbell-close-grip-press": ExerciseContentSource(title: "Dumbbell close grip bench press", url: "https://wger.de/api/v2/exerciseinfo/1228/", author: "Lynn_McIntyre", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "Lie down with your back on a flat bench. Hold a dumbbell in each hand. Raise your arms towards the ceiling with your palms facing each other and dumbbells pressed together.\nSlowly lower the dumbbells to your chest, then slowly push them back. Repeat the exercise."),
        "builtin.smith-close-grip-press": ExerciseContentSource(title: "Smith Machine Close-grip Bench Press", url: "https://wger.de/api/v2/exerciseinfo/598/", author: "tuckerm", licenseName: "CC-BY-SA 3", licenseURL: "https://creativecommons.org/licenses/by-sa/3.0/deed.en", originalDescription: "Perform a standard bench press on the smith machine, but have your hands on the bar about shoulder width apart, and keep your elbows close to your body."),
        "builtin.reverse-grip-bench-press": ExerciseContentSource(title: "Reverse Grip Bench Press", url: "https://wger.de/api/v2/exerciseinfo/498/", author: "bl0sh", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "Upper chest focuses exercise that also works triceps"),
        "builtin.pin-bench-press": ExerciseContentSource(title: "Pin Bench Press BB", url: "https://wger.de/api/v2/exerciseinfo/1436/", author: "M9", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "* Set security pins to about the height of your sticking point\n* Lower the bar, rest on the pins for 1s while holding tension\n* Move bar up with maximum force"),
        "builtin.incline-cable-fly": ExerciseContentSource(title: "Fly With Cable", url: "https://wger.de/api/v2/exerciseinfo/237/", author: "wger.de", licenseName: "CC-BY-SA 3", licenseURL: "https://creativecommons.org/licenses/by-sa/3.0/deed.en", originalDescription: "cable machine, two steps forward, straight back"),
        "builtin.seated-cable-fly": ExerciseContentSource(title: "Seated Cable chest fly", url: "https://wger.de/api/v2/exerciseinfo/1922/", author: "shushu", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "1. Place a bench between two cable pulleys and adjust the pulleys so they are at chest/shoulder height when you are seated.\n2. Grab the handles with a neutral grip and lean against the upright backrest.\n3. Bring your arms together in front of your chest in a controlled motion, focusing on squeezing your chest muscles. Keep your elbows slightly bent throughout the movement.\n4. Pause briefly at the top position.\n5. Slowly lower your arms back to the starting position while maintaining control of the movement.\n6. Repeat for reps."),
        "builtin.pec-deck-fly": ExerciseContentSource(title: "Butterfly", url: "https://wger.de/api/v2/exerciseinfo/135/", author: "wger.de", licenseName: "CC-BY-SA 3", licenseURL: "https://creativecommons.org/licenses/by-sa/3.0/deed.en", originalDescription: "Sit on the butterfly machine, the feet have a good contact with the floor, the upper arms are parallel to the floor. Press your arms together till the handles are practically together (but aren't!). Go slowly back. The weights should stay all the time in the air."),
        "builtin.hex-dumbbell-press": ExerciseContentSource(title: "Dumbbell Hex Press", url: "https://wger.de/api/v2/exerciseinfo/1353/", author: "Anastasious", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "* Engage the muscles\n* Position your feet wide\n* Controlled movement\n* Slow movement\n* Bring the weights toward your lower chest/stomach"),
        "builtin.barbell-reverse-row": ExerciseContentSource(title: "Bent Over Rowing Reverse", url: "https://wger.de/api/v2/exerciseinfo/84/", author: "wger.de", licenseName: "CC-BY-SA 3", licenseURL: "https://creativecommons.org/licenses/by-sa/3.0/deed.en", originalDescription: "The same as *regular* rowing, but holding a reversed grip (your palms pointing forwards):\n\nGrab the barbell with a wide grIp (slightly more than shoulder wide) and lean forward. Your upper body is not quite parallel to the floor, but forms a slight angle. The chest's out during the whole exercise.\n\nPull now the barbell with a fast movement towards your belly button, not further up. Go slowly down to the initial position. Don't swing with your body and keep your arms next to your body."),
        "builtin.t-bar-row": ExerciseContentSource(title: "Rowing, T-bar", url: "https://wger.de/api/v2/exerciseinfo/513/", author: "wger.de", licenseName: "CC-BY-SA 3", licenseURL: "https://creativecommons.org/licenses/by-sa/3.0/deed.en", originalDescription: "The execution of this exercise is very similar to the regular bent over rowing, only that the bar is fixed here.\n\nGrab the barbell with a wide grip (slightly more than shoulder wide) and lean forward. Your upper body is not quite parallel to the floor, but forms a slight angle. The chest's out during the whole exercise. Pull now the barbell with a fast movement towards your belly button, not further up. Go slowly down to the initial position. Don't swing with your body and keep your arms next to your body."),
        "builtin.pendlay-row": ExerciseContentSource(title: "Pendelay Rows", url: "https://wger.de/api/v2/exerciseinfo/448/", author: "Nallitnas", licenseName: "CC-BY-SA 3", licenseURL: "https://creativecommons.org/licenses/by-sa/3.0/deed.en", originalDescription: "Back excercise with a barbell with a starting position which is in a bent over position with the back paralell to the ground. The barbell is on the ground at chest level.For the movement grab the barbell at shoulder width grip and pull towards your chest without losing the bent over position and without moving anything but your arms"),
        "builtin.inverted-row": ExerciseContentSource(title: "Inverted Rows", url: "https://wger.de/api/v2/exerciseinfo/1198/", author: "Gavru", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "Maintain a straight body, retract your shoulder blades, and pull your\nchest to the bar for an effective back and upper body workout."),
        "builtin.suspension-row": ExerciseContentSource(title: "TRX Rows", url: "https://wger.de/api/v2/exerciseinfo/959/", author: "clafal", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "This exercise serves as a lead-up to Pull Ups."),
        "builtin.machine-seated-row": ExerciseContentSource(title: "Seated Row (Machine)", url: "https://wger.de/api/v2/exerciseinfo/1725/", author: "barry", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "Keep your chest up and squeeze your shoulder blades at the end.\n\nDon’t hunch forward or round your back during the pull."),
        "builtin.single-arm-cable-row": ExerciseContentSource(title: "Unilateral Cable row", url: "https://wger.de/api/v2/exerciseinfo/1621/", author: "Rottekongen", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "Put a vertical seated bench in front of the cable row machine.position it so that you can focus on one side, and then do slow pulls focusing on the lateral muscles and ensuring tention in those muscles when in a stretched position."),
        "builtin.close-grip-lat-pulldown": ExerciseContentSource(title: "Close-grip Lat Pull Down", url: "https://wger.de/api/v2/exerciseinfo/158/", author: "tuckerm", licenseName: "CC-BY-SA 3", licenseURL: "https://creativecommons.org/licenses/by-sa/3.0/deed.en", originalDescription: "Grip the pull-down bar with your hands closer than shoulder width apart, with your palms facing away from you. Lean back slightly. Pull the bar down towards your chest, keeping your elbows close to your sides as you come down. Pull your shoulders back at the end of the motion."),
        "builtin.supinated-lat-pulldown": ExerciseContentSource(title: "Close-grip supinated lat pulldown", url: "https://wger.de/api/v2/exerciseinfo/1127/", author: "Franpol", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "**Downward movement:**\n\n- Pull the bar down so that it passes close to your chin and touches the upper part of your chest.\n- Keep the rest of your body still."),
        "builtin.neutral-lat-pulldown": ExerciseContentSource(title: "Neutral-grip chest pulldown", url: "https://wger.de/api/v2/exerciseinfo/1136/", author: "Franpol", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "The lat pulldown is an important exercise for strengthening the back and improving posture, which can contribute to a healthier life. To perform this exercise correctly and avoid injury, it is important to follow a few key steps:\n\n1. Position yourself in front of the cable machine with your knees slightly bent and your feet on the floor.\n\n2. Grip the cable handle with your palms facing each other and your hands shoulder-width apart.\n\n3. Pull the handle down until it touches or comes close to your chest, holding the position for one or two seconds.\n\n4. Slowly raise the handle back to the starting position, making sure to keep your arms and hands straight and your back straight throughout the movement."),
        "builtin.straight-arm-pulldown": ExerciseContentSource(title: "Straight-Arm Pulldown (Cable)", url: "https://wger.de/api/v2/exerciseinfo/1726/", author: "barry", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "Keep arms straight but not locked, pulling with your lats, not your shoulders.\n\nDon’t let your shoulders shrug up during the movement."),
        "builtin.chin-up": ExerciseContentSource(title: "Chin Up", url: "https://wger.de/api/v2/exerciseinfo/152/", author: "BFad07", licenseName: "CC0", licenseURL: "http://creativecommons.org/publicdomain/zero/1.0/", originalDescription: "The chin-up (also known as a chin or chinup) is a strength training exercise. People frequently do this exercise with the intention of strengthening muscles such as the latissimus dorsi and biceps, which extend the shoulder and flex the elbow, respectively. In this maneuver, the palms are faced towards the body. It is a form of pull-up in which the range of motion is established in relation to a person's chin."),
        "builtin.commando-pull-up": ExerciseContentSource(title: "commando pull-ups", url: "https://wger.de/api/v2/exerciseinfo/980/", author: "clafal", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "variation of the pull-up exercise, it is performed with a grip of one hand supine and one hand prone, do not twist the torso to get back to the front, the head passes once to one side, once to the other."),
        "builtin.renegade-row": ExerciseContentSource(title: "Renegade Row", url: "https://wger.de/api/v2/exerciseinfo/490/", author: "fletchgraham", licenseName: "CC0", licenseURL: "http://creativecommons.org/publicdomain/zero/1.0/", originalDescription: "Get into pushup position gripping some dumbbells. Perform one pushup, then drive your left elbo up, bringing the dumbell up to your body. Return the dumbell to starting position.\n\nPerform another pushup and then row with the other arm to complete one rep."),
        "builtin.barbell-shrug": ExerciseContentSource(title: "Shrugs, Barbells", url: "https://wger.de/api/v2/exerciseinfo/571/", author: "wger.de", licenseName: "CC-BY-SA 3", licenseURL: "https://creativecommons.org/licenses/by-sa/3.0/deed.en", originalDescription: "Take a barbell and stand with a straight body, the arms are hanging freely in front of you. Lift from this position the shoulders as high as you can, but don't bend the arms during the movement. On the highest point, make a short pause of 1 or 2 seconds before returning slowly to the initial position.\n\nWhen training with a higher weight, make sure that you still do the whole movement!"),
        "builtin.dumbbell-shrug": ExerciseContentSource(title: "Shrugs, Dumbbells", url: "https://wger.de/api/v2/exerciseinfo/572/", author: "wger.de", licenseName: "CC-BY-SA 3", licenseURL: "https://creativecommons.org/licenses/by-sa/3.0/deed.en", originalDescription: "Stand with straight body, the hands are hanging freely on the side and hold each a dumbbell. Lift from this position the shoulders as high as you can, but don't bend the arms during the movement. On the highest point, make a short pause of 1 or 2 seconds before returning slowly to the initial position.\n\nWhen training with a higher weight, make sure that you still do the whole movement!"),
        "builtin.smith-shrug": ExerciseContentSource(title: "Shrugs on Multipress", url: "https://wger.de/api/v2/exerciseinfo/575/", author: "wger.de", licenseName: "CC-BY-SA 3", licenseURL: "https://creativecommons.org/licenses/by-sa/3.0/deed.en", originalDescription: ""),
        "builtin.back-extension": ExerciseContentSource(title: "Hyperextensions", url: "https://wger.de/api/v2/exerciseinfo/301/", author: "wger.de", licenseName: "CC-BY-SA 3", licenseURL: "https://creativecommons.org/licenses/by-sa/3.0/deed.en", originalDescription: "Lie on the hyperextension pillow with your navel at the front edge, allowing your upper body to hang freely. Tighten all your back muscles and raise your torso until you're horizontal, but no higher. Lower yourself slowly, maintaining a steady flow of muscles."),
        "builtin.machine-back-extension": ExerciseContentSource(title: "Seated Back Extension Machine", url: "https://wger.de/api/v2/exerciseinfo/1143/", author: "Franpol", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "1. Adjust the seat and the back pad so that the pad sits at the height of your shoulder blades or mid-back.\n2. Sit in the machine with your hips and lower back against the seat and backrest and your feet on the platform. Cross your arms over your chest or hold the handles.\n3. Exhale and push the pad backwards using your lower back muscles until your spine is in line with your hips. Pause for a second at the end position.\n4. Inhale and slowly return to the starting position, without letting the weight stack slam down."),
        "builtin.seated-barbell-shoulder-press": ExerciseContentSource(title: "Shoulder Press, Barbell", url: "https://wger.de/api/v2/exerciseinfo/566/", author: "wger.de", licenseName: "CC-BY-SA 3", licenseURL: "https://creativecommons.org/licenses/by-sa/3.0/deed.en", originalDescription: "Sit on a bench, the back rest should be almost vertical. Take a barbell with a shoulder wide grip and bring it up to chest height. Press the weight up, but don't stretch the arms completely. Go slowly down and repeat."),
        "builtin.standing-barbell-overhead-press": ExerciseContentSource(title: "Overhead Barbell Press", url: "https://wger.de/api/v2/exerciseinfo/1893/", author: "nishant0712", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "- **Setup:** Stand with feet together and grip the bar slightly wider than shoulders.\n- **Position:** Rest the bar on your upper chest.\n- **Press:** Brace your core and push the bar straight up until your arms lock out.\n- **Finish:** Control the bar back down to your chest.\n- https://youtu.be/ZXpdJOLNoWw?si=u27cGyODoblXHBu1"),
        "builtin.arnold-press": ExerciseContentSource(title: "Arnold Shoulder Press", url: "https://wger.de/api/v2/exerciseinfo/20/", author: "trzr23", licenseName: "CC-BY-SA 3", licenseURL: "https://creativecommons.org/licenses/by-sa/3.0/deed.en", originalDescription: "Sit on a bench with your back supported. Hold a pair of dumbbells in front of your shoulders, palms facing you and elbows in front of your body.\n\nPress the dumbbells overhead while rotating your hands, so that your palms face forward at the top. Stop just before your elbows lock out.\n\nReverse the movement under control: lower the dumbbells and turn your palms back towards you until you are in the starting position again.\n\nAs shown here: https://www.youtube.com/watch?v=vj2w851ZHRM"),
        "builtin.smith-shoulder-press": ExerciseContentSource(title: "Shoulder Press, on Multi Press", url: "https://wger.de/api/v2/exerciseinfo/569/", author: "wger.de", licenseName: "CC-BY-SA 3", licenseURL: "https://creativecommons.org/licenses/by-sa/3.0/deed.en", originalDescription: "The exercise is basically the same as with a free barbell:\n\nSit on a bench, the back rest should be almost vertical. Take a bar with a shoulder wide grip and bring it down to chest height. Press the weight up, but don't stretch the arms completely. Go slowly down and repeat."),
        "builtin.landmine-press": ExerciseContentSource(title: "Landmine press", url: "https://wger.de/api/v2/exerciseinfo/346/", author: "Torsten Linnecke", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: ""),
        "builtin.dumbbell-front-raise": ExerciseContentSource(title: "Front Raises", url: "https://wger.de/api/v2/exerciseinfo/256/", author: "Manu, wikipedia", licenseName: "CC-BY-SA 3", licenseURL: "https://creativecommons.org/licenses/by-sa/3.0/deed.en", originalDescription: "To execute the exercise, the lifter stands with their feet shoulder width apart and weights or resistance handles held by their side with a pronated (overhand) grip.\n\nThe movement is to bring the arms up in front of the body to eye level and with only a slight bend in the elbow. This isolates the anterior deltoid muscle (front of the shoulder) and uses the anterior deltoid to lift the weight.\n\nWhen lifting it is important to keep the body still so the anterior deltoid is fully utilised; if the weight cannot be lifted by standing still then it is too heavy and a lower weight is needed. It is important to keep a slight bend in the elbow when lifting as keeping the elbow locked will add stress to the elbow joint and could cause injury.\n\nA neutral grip, similar to that used in the hammer curl, can also be used. With this variation the weight is again raised to eye level, but out to a 45 degree angle from the front of the body. This may be beneficial for those with shoulder injuries, particularly those related to the rotator cuff."),
        "builtin.machine-lateral-raise": ExerciseContentSource(title: "Machine Lateral Raise", url: "https://wger.de/api/v2/exerciseinfo/1654/", author: "roneydya", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "The machine lateral raise is an isolation exercise that targets the medial (side) deltoid muscle to build wider, more defined shoulders. The machine's fixed path of motion provides greater stability than dumbbells, making it ideal for beginners or those who want to focus solely on muscle activation."),
        "builtin.cable-rear-delt-fly": ExerciseContentSource(title: "Cable Rear Delt Fly", url: "https://wger.de/api/v2/exerciseinfo/822/", author: "cshep442", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "The reverse cable fly, also known as the cable rear delt fly, is a deltoid muscle strengthening and definition exercise. It’s one of the best isolation exercises for your back and posterior deltoid.This workout targets your posterior (back) deltoids while using a range of upper body muscles.\n\n1. Adjust the weight and the pulleys to the right height. You should be able to see the pulleys because they should be above your head.\n2. With your right hand, grab the left pulley, and with your left hand, grab the right pulley, crossing them in front of you. This is where you’ll begin your journey.\n3. Start the movement by moving your arms back and forth while keeping your arms straight.\n4. Pause at the finish of the move for a brief moment before returning the handles to their starting positions."),
        "builtin.incline-reverse-fly": ExerciseContentSource(title: "Incline Bench Reverse Fly", url: "https://wger.de/api/v2/exerciseinfo/828/", author: "cshep442", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "The incline dumbbell reverse fly is an upper-body exercise targeting the posterior or rear deltoids, as well as the postural muscles of the upper back. Because it targets such small muscles, this exercise is usually performed with light weight for high reps, such as 10-15 reps per set or more."),
        "builtin.seated-reverse-fly": ExerciseContentSource(title: "Seated rear delt rise", url: "https://wger.de/api/v2/exerciseinfo/1098/", author: "philip", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "Seated, bent 45 deg forward. Arms fully stretched out, raise arms up to shoulder height and back down"),
        "builtin.dumbbell-rear-delt-row": ExerciseContentSource(title: "Dumbbell rear delt row", url: "https://wger.de/api/v2/exerciseinfo/1227/", author: "Lynn_McIntyre", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "Hold a dumbbell in each hand. Bend at your hips to make your back almost parallel to the floor. Let your arms hang down. Keep your arms in line with your shoulders. bend and lift your elbows out to the sides until your upper arms are parallel to the floor. Slowly return and repeat"),
        "builtin.band-face-pull": ExerciseContentSource(title: "Face pulls with yellow/green band", url: "https://wger.de/api/v2/exerciseinfo/1732/", author: "54str", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "Face pulls with band – standing horizontal pull. Grab the band at face height, pull elbows high and wide towards your face while squeezing shoulder blades together. Trains upper back, rear shoulders and improves posture."),
        "builtin.ez-bar-curl": ExerciseContentSource(title: "Biceps Curls With SZ-bar", url: "https://wger.de/api/v2/exerciseinfo/94/", author: "wger.de", licenseName: "CC-BY-SA 3", licenseURL: "https://creativecommons.org/licenses/by-sa/3.0/deed.en", originalDescription: "Hold the SZ-bar shoulder-wide, the back is straight, the shoulders slightly back, the arms are streched. Bend the arms, bringing the weight up, with a fast movement. Without pausing, let down the bar with a slow and controlled movement.\n\nDon't allow your body to swing during the exercise, all work is done by the biceps, which are the only mucles that should move (pay attention to the elbows)."),
        "builtin.preacher-curl": ExerciseContentSource(title: "Preacher Curls", url: "https://wger.de/api/v2/exerciseinfo/465/", author: "cgoob883", licenseName: "CC-BY-SA 3", licenseURL: "https://creativecommons.org/licenses/by-sa/3.0/deed.en", originalDescription: "Place the EZ curl bar on the rest handles in front of the preacher bench. Lean over the bench and grab the EZ curl bar with palms up. Sit down on the preacher bench seat so your upper arms rest on top of the pad and your chest is pressed against the pad. Lower the weight until your elbows are extended and arms are straight. Bring the weights back up to the starting point by contracting biceps. Repeat"),
        "builtin.concentration-curl": ExerciseContentSource(title: "Dumbbell Concentration Curl", url: "https://wger.de/api/v2/exerciseinfo/202/", author: "http://www.exrx.net/WeightExercises/Brachialis/DBC", licenseName: "CC-BY-SA 3", licenseURL: "https://creativecommons.org/licenses/by-sa/3.0/deed.en", originalDescription: "Sit on bench. Grasp dumbbell between feet. Place back of upper arm to inner thigh. Lean into leg to raise elbow slightly."),
        "builtin.incline-dumbbell-curl": ExerciseContentSource(title: "Dumbbell Incline Curl", url: "https://wger.de/api/v2/exerciseinfo/204/", author: "ExRx", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "- **Setup:** Set an adjustable bench to an incline of approximately **45 to 60 degrees**.\n- **Starting Position:** Sit back against the bench with a dumbbell in each hand. Let your arms hang straight down toward the floor with your palms facing forward (supinated grip).\n- **The Curl:** Keeping your upper arms stationary and shoulders pinned back against the bench, exhale and curl the weights upward toward your shoulders.\n- **Peak Contraction:** Squeeze your biceps hard at the top of the movement, ensuring your elbows do not swing forward.\n- **The Descent:** Inhale and slowly lower the dumbbells back to the starting position, maintaining full control and feeling the stretch in the biceps."),
        "builtin.reverse-barbell-curl": ExerciseContentSource(title: "Reverse Grip Barbell Curls", url: "https://wger.de/api/v2/exerciseinfo/1290/", author: "sTiKyt", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "Hold the barbell with an overhand grip (palms facing down) approximately shoulder-width apart. Ensure your back is straight, shoulders slightly pulled back, and arms fully extended.\nCurl the barbell upwards towards your chest in a controlled motion, keeping your elbows close to your body. The motion should be smooth without any swinging or momentum use.\nOnce the barbell is at chest level, pause briefly to maximize contraction in the biceps and forearms.\nSlowly lower the barbell back to the starting position with a controlled movement, fully extending your arms."),
        "builtin.cable-hammer-curl": ExerciseContentSource(title: "Hammercurls on Cable", url: "https://wger.de/api/v2/exerciseinfo/275/", author: "wger.de", licenseName: "CC-BY-SA 3", licenseURL: "https://creativecommons.org/licenses/by-sa/3.0/deed.en", originalDescription: "Take a cable in your hands (palms parallel, point to each other), the body is straight. Bend the arms and bring the weight up with a fast movement. Without any pause bring it back down with a slow, controlled movement, but don't stretch completely your arms.\n\nDon't swing your body during the exercise, the biceps should do all the work here. The elbows are at your side and don't move."),
        "builtin.cable-concentration-curl": ExerciseContentSource(title: "Cable Concentration Curl", url: "https://wger.de/api/v2/exerciseinfo/1109/", author: "cshep442", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "The concentration curl is a classic exercise for building the biceps one arm at a time. It can be performed bent over or kneeling, but is more often performed seated on a bench. It's great for emphasizing the biceps peak and is often used to finish a biceps workout"),
        "builtin.machine-biceps-curl": ExerciseContentSource(title: "Biceps Curl Machine", url: "https://wger.de/api/v2/exerciseinfo/1424/", author: "hpmbala@gmail.com", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "The biceps curl machine is designed to isolate the biceps muscles and provide a controlled range of motion. Sit on the machine with your back against the pad and adjust the seat so your arms are aligned with the machine's handles or pads. Grip the handles firmly, keeping your elbows fixed in place, and curl the handles upward by contracting your biceps. Slowly lower the handles to the starting position, maintaining control throughout the movement."),
        "builtin.seated-dumbbell-curl": ExerciseContentSource(title: "Seated Dumbbell Curls", url: "https://wger.de/api/v2/exerciseinfo/1289/", author: "sTiKyt", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "Seated Dumbbell Curls are an effective bicep workout that isolates the muscles by stabilizing the upper body, reducing momentum that can detract from the exercise’s effectiveness. This exercise is performed sitting down with a dumbbell in each hand, focusing on controlled movement to maximize engagement of the bicep muscles."),
        "builtin.dumbbell-drag-curl": ExerciseContentSource(title: "Dumbbell drag curls", url: "https://wger.de/api/v2/exerciseinfo/1224/", author: "Lynn_McIntyre", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "Hold a dumbbell in each hand with your palms facing forward. Pull your elbows back and lift the dumbbells to your chest height. Slowly lower the dumbbell and repeat the exercise."),
        "builtin.wide-dumbbell-curl": ExerciseContentSource(title: "Dumbbell wide bicep curls", url: "https://wger.de/api/v2/exerciseinfo/1225/", author: "Lynn_McIntyre", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "Hold a dumbbell in each hand with your hands slightly wider than shoulder-width apart and palms facing forward.\nBend your elbows and lift the dumbbells to your shoulders. Slowly return and repeat."),
        "builtin.barbell-wrist-curl": ExerciseContentSource(title: "Barbell Wrist Curl", url: "https://wger.de/api/v2/exerciseinfo/51/", author: "burenl", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "Sitting on a bench, grab a barbell with your palms facing up and your hands shoulder-width apart. Rest your forearms on your thighs and allow your wrists to hang over your knees. Perform the movement by curling your palms and wrists towards your face.\n\nPause for a moment in the top position, then slowly return the barbell to the starting position."),
        "builtin.barbell-reverse-wrist-curl": ExerciseContentSource(title: "Barbell Reverse Wrist Curl", url: "https://wger.de/api/v2/exerciseinfo/48/", author: "burenl", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "Sitting on a bench, grab a barbell with your palms facing down and your hands shoulder-width apart. Rest your forearms on your thighs and allow your wrists to hang over your knees.\n\nCurl your knuckles towards your face, lifting the barbell. Pause for a moment in the top position, then slowly return the barbell to the starting position."),
        "builtin.dumbbell-wrist-curl": ExerciseContentSource(title: "Wrist curl, dumbbells", url: "https://wger.de/api/v2/exerciseinfo/1205/", author: "wakanda90", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "1. Sitting on a bench, grab the dumbbell with your palms facing up\n   and your hands shoulder-width apart. Rest your forearms on your thighs\n   and allow your wrists to hang over your knees.\n2. Perform the movement by\n   curling your palms and wrists towards your face.\n3. (optional/variable) Pause at the top.\n4. Slowly return to the starting position."),
        "builtin.lying-barbell-triceps-extension": ExerciseContentSource(title: "Barbell Triceps Extension", url: "https://wger.de/api/v2/exerciseinfo/50/", author: "sevae", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "Position barbell overhead with narrow overhand grip.\n\nLower forearm behind upper arm with elbows remaining overhead. Extend forearm overhead. Lower and repeat."),
        "builtin.bench-dip": ExerciseContentSource(title: "Dips Between Two Benches", url: "https://wger.de/api/v2/exerciseinfo/197/", author: "wger.de", licenseName: "CC-BY-SA 3", licenseURL: "https://creativecommons.org/licenses/by-sa/3.0/deed.en", originalDescription: "Put two benches so far appart, that you can hold onto one with your hands and are just able to reach the other with your feet. The legs stay during the exercise completely stretched. With your elbows facing back, bend them as much as you can. Push yourself up, but don't stretch out the arms."),
        "builtin.parallel-bar-dip": ExerciseContentSource(title: "Dips", url: "https://wger.de/api/v2/exerciseinfo/194/", author: "BFad07", licenseName: "CC0", licenseURL: "http://creativecommons.org/publicdomain/zero/1.0/", originalDescription: "A dip is an upper-body strength exercise. Narrow, shoulder-width dips primarily train the triceps, with major synergists being the anterior deltoid, the pectoralis muscles (sternal, clavicular, and minor), and the rhomboid muscles of the back (in that order).[1] Wide arm training places additional emphasis on the pectoral muscles, similar in respect to the way a wide grip bench press would focus more on the pectorals and less on the triceps."),
        "builtin.ring-dip": ExerciseContentSource(title: "Ring Dips", url: "https://wger.de/api/v2/exerciseinfo/501/", author: "Nash", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "Dips peformed on gymnastic rings."),
        "builtin.assisted-dip": ExerciseContentSource(title: "Triceps Dips (Assisted)", url: "https://wger.de/api/v2/exerciseinfo/1372/", author: "matpn", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "Assisted triceps dips  is a gym work out exercise that targets triceps and also involves chest."),
        "builtin.floor-dip": ExerciseContentSource(title: "Floor dips", url: "https://wger.de/api/v2/exerciseinfo/1000/", author: "Upstream contributor not specified", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "Starting position:\n\nSit with your arms behind you, supporting your back.Your fingers should point forward.Your knees should be bent, feet together.\n\nSteps:\n\n1. Raise your hips off the ground, straightening your arms.\n2. Bend your elbows, bringing your hips down.\n3. Straighten your arms, returning to the previous position.\n4. Repeat steps 2 and 3.\n\nNotes:\n\nThe exercise's difficulty depends on how high you bring your hips."),
        "builtin.standing-leg-curl": ExerciseContentSource(title: "Leg Curls (standing)", url: "https://wger.de/api/v2/exerciseinfo/367/", author: "wger.de", licenseName: "CC-BY-SA 3", licenseURL: "https://creativecommons.org/licenses/by-sa/3.0/deed.en", originalDescription: ""),
        "builtin.single-leg-curl": ExerciseContentSource(title: "Single-leg hamstring curl", url: "https://wger.de/api/v2/exerciseinfo/1294/", author: "clafal", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "Specifically, the muscles involved are: biceps femoris, semimembranosus and semitendinosus."),
        "builtin.hack-squat": ExerciseContentSource(title: "Leg Press on Hackenschmidt Machine", url: "https://wger.de/api/v2/exerciseinfo/375/", author: "wger.de", licenseName: "CC-BY-SA 3", licenseURL: "https://creativecommons.org/licenses/by-sa/3.0/deed.en", originalDescription: ""),
        "builtin.smith-squat": ExerciseContentSource(title: "Squats on Multipress", url: "https://wger.de/api/v2/exerciseinfo/341/", author: "wger.de", licenseName: "CC-BY-SA 3", licenseURL: "https://creativecommons.org/licenses/by-sa/3.0/deed.en", originalDescription: ""),
        "builtin.pendulum-squat": ExerciseContentSource(title: "Pendular hack", url: "https://wger.de/api/v2/exerciseinfo/1521/", author: "polloperro", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "Pendulum hack, made on a pendulum machine"),
        "builtin.wide-leg-press": ExerciseContentSource(title: "Leg Presses (wide)", url: "https://wger.de/api/v2/exerciseinfo/374/", author: "wger.de", licenseName: "CC-BY-SA 3", licenseURL: "https://creativecommons.org/licenses/by-sa/3.0/deed.en", originalDescription: "Sit on the machine and put your feet on the platform, a bit more than shoulder wide. The feet are turned outwards by a few degrees.\n\nLower the weight so much, that the knees form a right angle. Push immediately the platform up again, without any pause. When in the lower position, the knees point a bit outwards and the movement should be always fluid."),
        "builtin.narrow-leg-press": ExerciseContentSource(title: "Leg Presses (narrow)", url: "https://wger.de/api/v2/exerciseinfo/373/", author: "wger.de", licenseName: "CC-BY-SA 3", licenseURL: "https://creativecommons.org/licenses/by-sa/3.0/deed.en", originalDescription: "The exercise is very similar to the wide leg press:\n\nSit on the machine and put your feet on the platform so far apart  that you could just put another foot in between them. The feet are parallel and point up.\n\nLower the weight so much, that the knees form a right angle. Push immediately the platform up again, without any pause. When in the lower position, the knees point a bit outwards and the movement should be always fluid."),
        "builtin.dumbbell-front-squat": ExerciseContentSource(title: "Dumbbell Front Squat", url: "https://wger.de/api/v2/exerciseinfo/1640/", author: "AlucardEvil40", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "This exercise involves holding a dumbbell in each hand at shoulder height and performing a squat. It targets the lower body muscles, including the quads, hamstrings, and glutes, while also engaging the core and upper body."),
        "builtin.double-kettlebell-front-squat": ExerciseContentSource(title: "Double Kettlebell Front Squat", url: "https://wger.de/api/v2/exerciseinfo/1361/", author: "m4k3r", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "The kettlebell front squat is a compound, multi-joint exercise that works several muscle groups."),
        "builtin.sumo-squat": ExerciseContentSource(title: "Sumo Squats", url: "https://wger.de/api/v2/exerciseinfo/632/", author: "sophialj", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "Stand with your feet wider than your shoulders, with your toes pointed out at a 45 degree angle and barbell on your shoulder.\n\nWhile keeping your back straight, descend slowly by bending at the knees and hips as if you are sitting down (squatting).\n\nLower yourself until your quadriceps and hamstrings are parallel to the floor.\n\nReturn to the starting position by pressing upwards and extending your legs while maintaining an equal distribution of weight on your forefoot and heel."),
        "builtin.prisoner-squat": ExerciseContentSource(title: "Prisoner Squat", url: "https://wger.de/api/v2/exerciseinfo/1208/", author: "lxmx", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "Stand upright with your chest slightly raised, your feet hip-width apart and your toes pointing straight ahead.\nBring your hands to the back of your head with your fingers slightly interlaced and your elbows pointing to the side. Push your hips back and bend your knees, keeping your upper body as upright as possible. \nPush your knees outwards, they must never point towards each other. If your upper body moves slightly forward, make sure that it does not bend. Always keep your elbows level with your ears by tensing the muscles between your shoulder blades. If you are flexible enough, you can sink down until your buttocks touch your calves.\nHowever, make sure that you do not bend your spine. \nBefore this happens, reverse the movement and use your heels and glutes to push yourself upwards with so much momentum that your feet lift off briefly and you do a little hop. \nIf necessary, correct the position of your feet, arms and upper body before you move on to the next repetition.\nTranslated with www.DeepL.com/Translator (free version)"),
        "builtin.cossack-squat": ExerciseContentSource(title: "Cossack squat", url: "https://wger.de/api/v2/exerciseinfo/1407/", author: "clafal", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "The Cossack Squat is a multi-joint exercise that works mainly on the legs and buttocks, but also involves stabilizing muscles. It is an excellent exercise for improving strength, mobility and stability in a functional way."),
        "builtin.lateral-lunge": ExerciseContentSource(title: "Side split squats left", url: "https://wger.de/api/v2/exerciseinfo/986/", author: "Upstream contributor not specified", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "Starting position:\n\n1. Stand tall and take a wide lateral stride, just greater than shoulder width.\n\nSteps:\n\n1. Bend one knee until your thigh is parallel to the floor. The bent knee must be in line with the foot.\n2. Push back to the starting position.\n3. Repeat."),
        "builtin.sliding-lateral-lunge": ExerciseContentSource(title: "Sliding Lateral Lunge", url: "https://wger.de/api/v2/exerciseinfo/1604/", author: "RiccaBaro", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "Stand upright with your feet hip-width apart, holding a kettlebell close to your chest in goblet position. Place one foot on a slider, gliding disc, or towel. Keep your chest tall and core engaged. Slowly slide the foot outward to the side while bending the opposite knee, lowering your hips into a lateral lunge. Keep the working leg’s knee aligned with the toes and avoid letting it collapse inward. The non-working leg remains straight and slides smoothly along the floor. Push through the heel of the bent leg to return to the starting position while maintaining control of the kettlebell."),
        "builtin.bulgarian-split-squat": ExerciseContentSource(title: "Bulgarian split squats left", url: "https://wger.de/api/v2/exerciseinfo/988/", author: "Upstream contributor not specified", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "1. Stand tall in front of a chair and take a large step. Put the upper part of one of your feet on the chair.\n2. Bend the front knee, balancing with arms until the back knee almost touches the ground.\n3. Push back to the starting position and repeat."),
        "builtin.dumbbell-bulgarian-split-squat": ExerciseContentSource(title: "Bulgarian Squat with Dumbbells", url: "https://wger.de/api/v2/exerciseinfo/1706/", author: "AlucardEvil40", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "The Bulgarian split squat consists of performing a squat on one leg with the rear foot resting on a raised platform. Elevating your back leg on a bench creates instability and increases the range of motion of the exercise."),
        "builtin.dumbbell-split-squat": ExerciseContentSource(title: "Dumbbell Split Squat", url: "https://wger.de/api/v2/exerciseinfo/1366/", author: "Anastasious", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "* Controlled execution\n* No momentum\n* Execute slowly"),
        "builtin.barbell-lunge": ExerciseContentSource(title: "Barbell Lunges Standing", url: "https://wger.de/api/v2/exerciseinfo/46/", author: "Mikko Ruohola", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "Put barbell on the back of your shoulders. Stand upright, then take the first step forward. Step should bring you forward so that your supporting legs knee can touch the floor. Then stand back up and repeat with the other leg.\n\nRemember to keep good posture."),
        "builtin.barbell-reverse-lunge": ExerciseContentSource(title: "Barbell Step Back Lunge", url: "https://wger.de/api/v2/exerciseinfo/1830/", author: "Upstream contributor not specified", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "1. Stand with your feet hip-width apart, holding a barbell on your upper back.\n2. Keep your back straight, chest up, and core engaged.\n3. Take a step back with one leg and lower your body by bending both knees. Ensure that your back knee nearly touches the ground.\n4. Push off your back foot to return to the starting position.\n5. Repeat the movement with the other leg.\n\nContinue alternating between legs for the desired repetitions."),
        "builtin.walking-dumbbell-lunge": ExerciseContentSource(title: "Dumbbell Lunges Walking", url: "https://wger.de/api/v2/exerciseinfo/206/", author: "wger.de", licenseName: "CC-BY-SA 3", licenseURL: "https://creativecommons.org/licenses/by-sa/3.0/deed.en", originalDescription: "- **Starting Position:** Stand with feet hip-width apart and hands either on your hips or holding dumbbells at your sides.\n- **The Stride:** Take a wide step forward with your right leg.\n- **The Descent:** Lower your hips until both knees are bent at approximately **90-degree angles**.\n- **The Transition:** Drive through your front heel to stand up, bringing your back foot forward to step directly into the next lunge."),
        "builtin.step-up": ExerciseContentSource(title: "Step-ups", url: "https://wger.de/api/v2/exerciseinfo/981/", author: "Upstream contributor not specified", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "Starting position:\n\nStand facing a chair.\n\nSteps:\n\n1. Step up onto the chair.\n2. Step off the chair.\n3. Repeat."),
        "builtin.weighted-step-up": ExerciseContentSource(title: "Weighted Step-ups", url: "https://wger.de/api/v2/exerciseinfo/722/", author: "jigglychipmunk", licenseName: "CC0", licenseURL: "http://creativecommons.org/publicdomain/zero/1.0/", originalDescription: "box step ups w/ barbell and 45's on each side"),
        "builtin.single-leg-calf-raise": ExerciseContentSource(title: "Calf raises, one legged", url: "https://wger.de/api/v2/exerciseinfo/702/", author: "McMarcel13", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: ""),
        "builtin.leg-press-calf-raise": ExerciseContentSource(title: "Calf Press Using Leg Press Machine", url: "https://wger.de/api/v2/exerciseinfo/146/", author: "nate303303", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "Put  the balls of your feet on an extended leg press pad.  Use your calves to press the weight by flexing your feet/toes into a pointed position, and releasing back into a relaxed position.\n\nThis exercise builds mass and strength in the Gastrocnemius and Soleus muscles as well, if not better, than any calf exercise."),
        "builtin.hack-machine-calf-raise": ExerciseContentSource(title: "Calf Raises on Hackenschmitt Machine", url: "https://wger.de/api/v2/exerciseinfo/148/", author: "wger.de", licenseName: "CC-BY-SA 3", licenseURL: "https://creativecommons.org/licenses/by-sa/3.0/deed.en", originalDescription: "Place yourself on the machine with your back firmly against the backrest, the feet are on the platform for calf raises. Check that the feet are half free and that you can completely stretch the calf muscles down.\n\nWith straight knees pull up your weight as much as you can. Go with a fluid movement down till the calves are completely stretched. Repeat."),
        "builtin.sumo-deadlift": ExerciseContentSource(title: "Sumo Deadlift", url: "https://wger.de/api/v2/exerciseinfo/630/", author: "magdy", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "1. Begin with a bar loaded on the ground. Approach the bar so that the bar intersects the middle of the feet. The feet should be set very wide, near the collars. Bend at the hips to grip the bar. The arms should be directly below the shoulders, inside the legs, and you can use a pronated grip, a mixed grip, or hook grip. Relax the shoulders, which in effect lengthens your arms.\n2. Take a breath, and then lower your hips, looking forward with your head with your chest up. Drive through the floor, spreading your feet apart, with your weight on the back half of your feet. Extend through the hips and knees.\n3. As the bar passes through the knees, lean back and drive the hips into the bar, pulling your shoulder blades together.\n4. Return the weight to the ground by bending at the hips and controlling the weight on the way down."),
        "builtin.kettlebell-deadlift": ExerciseContentSource(title: "Kettlebell deadlifts", url: "https://wger.de/api/v2/exerciseinfo/1003/", author: "Upstream contributor not specified", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "Starting position:\n\nStand hip-width apart, with your kettlebell centered between your ankles. Your back should be straight, your head facing forward.\n\nSteps:\n\n1. Hinge at the hips and slightly bend at the knees to put your hands on the kettlebell handles. Your back should be straight as you perform the movement.\n2. Grab the kettlebell handles, with your hands pushing in opposite directions as if to pull the handle apart.\n3. While contacting your abs and glutes, stand straight up.\n4. Hinge at the hips again to bring the kettlebell back down, similarly to step 1.\n5. Repeat from step 3.\n\nTips:\n\n* Be sure you're performing the movements correctly, as doing otherwise can lead to injury. For example, do not squat instead of hinging at the hips, do not round your back while reaching for the kettlebell, and do not lean back while standing up."),
        "builtin.dumbbell-deadlift": ExerciseContentSource(title: "Dumbbell Deadlift", url: "https://wger.de/api/v2/exerciseinfo/1370/", author: "Anastasious", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "* Controlled execution\n* Don't use momentum\n* Slow execution"),
        "builtin.dumbbell-sumo-deadlift": ExerciseContentSource(title: "Dumbbell sumo deadlift", url: "https://wger.de/api/v2/exerciseinfo/1088/", author: "philip", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "Lower your dumbbell to the ground between your legs. Assume a wide stance and with a straight back squat down. With the dumbbell standing upright, grip it by the top of the ‘head’ (picture 1).Keeping your chest up and core braced, push the floor away, driving back upwards to a standing position (picture 2). Repeat. If you can easily achieve 20-30 reps, use two dumbbells."),
        "builtin.single-leg-dumbbell-rdl": ExerciseContentSource(title: "Single-Leg Deadlift with Dumbbell", url: "https://wger.de/api/v2/exerciseinfo/1736/", author: "Tierrasverdes", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "Starting Position: Stand upright with a slight bend in your knees, holding a dumbbell in one or both hands. Shift your weight onto your supporting leg (e.g., your right leg) and lift your non-supporting foot slightly off the floor.\n\nThe Hinge: Keeping your back flat and core engaged, hinge at your hips, pushing your glutes backward. As your torso lowers, extend your non-supporting leg straight back behind you for balance, keeping your hips square to the floor. The dumbbell(s) should lower toward the ground along the line of your supporting leg.\n\nRange of Motion: Continue lowering your torso until it is nearly parallel to the floor, or you feel an intense stretch in your supporting hamstring, ensuring your back remains neutral throughout the movement.\n\nReturn to Start: Pause at the bottom, then contract your glutes and hamstrings to slowly raise your torso back to the starting position. Your non-supporting leg should return in line with the supporting one.\n\nSwitch Sides: After completing your desired number of repetitions on one side, switch your weight and repeat the movement on the other leg."),
        "builtin.single-leg-kettlebell-rdl": ExerciseContentSource(title: "Kettlebell One Legged Deadlift", url: "https://wger.de/api/v2/exerciseinfo/1641/", author: "AlucardEvil40", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "This exercise involves holding a kettlebell in one hand and standing on one leg while bending forward to touch the kettlebell to the ground. It targets the hamstrings, glutes, and lower back while also improving balance and stability."),
        "builtin.rack-pull": ExerciseContentSource(title: "Rack Deadlift", url: "https://wger.de/api/v2/exerciseinfo/484/", author: "Mahoney", licenseName: "CC-BY-SA 3", licenseURL: "https://creativecommons.org/licenses/by-sa/3.0/deed.en", originalDescription: "Deadlift to be done using a Smith machine or a free rack. Bar or barbell hould be just right under the knee cap level. Lift using the glutes and through the heels, then come back to starting postion with a control movement of 2 seconds.\n\nThis exercise targets mainly the lower back and glutes."),
        "builtin.good-morning": ExerciseContentSource(title: "Good Morning", url: "https://wger.de/api/v2/exerciseinfo/1392/", author: "captive0592", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "Stand with your feet more than shoulder-width apart (wider stance) and place your hands on your hips. Hinge at your hips and lower your upper body towards the ground while keeping your back straight then come back up."),
        "builtin.dumbbell-hip-thrust": ExerciseContentSource(title: "Dumbbell Hip Thrust", url: "https://wger.de/api/v2/exerciseinfo/1642/", author: "AlucardEvil40", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "This exercise involves sitting on the ground with a dumbbell resting on the hips, then thrusting the hips upward while squeezing the glutes. It is a great exercise for strengthening the glutes and improving hip mobility."),
        "builtin.cable-glute-kickback": ExerciseContentSource(title: "Cable glute extension", url: "https://wger.de/api/v2/exerciseinfo/1131/", author: "Franpol", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "This exercise lets you work the upper, or larger, part of the glutes. For that reason, it should never be missing from your routine of isolated exercises for training the glutes.\nStand in front of a cable machine and locate the low pulley. Then attach the ankle strap to work on the low pulley. As for your posture, you should stay upright at all times. Pay special attention to your back to keep it straight and avoid injury.\nIt is advisable to hold on to the machine for better balance. With the leg that is holding the weight of the cable, perform a slow stretch backward without bending the knee."),
        "builtin.wall-sit": ExerciseContentSource(title: "Wall Squat", url: "https://wger.de/api/v2/exerciseinfo/718/", author: "Blablabla", licenseName: "CC0", licenseURL: "http://creativecommons.org/publicdomain/zero/1.0/", originalDescription: "Find a nice flat piece of wall and stand with your back leaning against the wall. Slowly slide down the wall while moving your feet away from it, until your thighs are parallel to the ground and both your knees and your hips are bent at a 90° angle. Cross your arms in front of your chest and hold this position for 30 seconds.\n\nVariant: put a big inflated rubber ball (like a small basketball) between your knees and squeeze the ball while holding the squat position"),
        "builtin.high-plank": ExerciseContentSource(title: "High plank", url: "https://wger.de/api/v2/exerciseinfo/1001/", author: "Upstream contributor not specified", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "Starting position:\n\nGet into the high plank position:your hands and toes should be touching the ground, your back, arms and legs should be straight.To get to this position, you can lie down on your stomach, place your hands facing down next to your head, and lifting your arms up until they are straight.\n\nSteps:\n\n1. Maintain the starting position for the entire duration of the exercise."),
        "builtin.reverse-plank": ExerciseContentSource(title: "Reverse Plank", url: "https://wger.de/api/v2/exerciseinfo/500/", author: "spacetowaste", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "Plank with stomach towards ceiling"),
        "builtin.plank-shoulder-tap": ExerciseContentSource(title: "Plank Shoulder Taps", url: "https://wger.de/api/v2/exerciseinfo/1091/", author: "clafal", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "In the correct plank position, place your feet slightly wider than shoulder-width apart. alternately lift and touch the opposite shoulder with one hand."),
        "builtin.plank-leg-lift": ExerciseContentSource(title: "Plank with Alternating Leg Lift", url: "https://wger.de/api/v2/exerciseinfo/1410/", author: "hpmbala@gmail.com", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "In a plank position, lift one leg alternately."),
        "builtin.pallof-press": ExerciseContentSource(title: "Pallof Press", url: "https://wger.de/api/v2/exerciseinfo/1194/", author: "prevail90", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "The Pallof press is an anti-rotation exercise that trains the larger and smaller muscles around the spine to resist rotation.\n\n* Stand parallel to the cable machine or to the anchor point to the\n  resistance band and clasp with the handle or band with both hands.\n* Make sure your torso is front on and bring your hands to the center of your chest and slowly press out.\n* Slowly return your hands to the chest and repeat."),
        "builtin.russian-twist": ExerciseContentSource(title: "Russian Twist", url: "https://wger.de/api/v2/exerciseinfo/1193/", author: "lion", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "1. Hold a dumbbell, barbell weight or something else that is heavy with both hands, but make sure it is not too heavy and you are able to keep in form.\n2. Lean back to a 45-degree angle from the floor. For an extra challenge, lift your feet off the floor.\n3. Rotate your arms to one side to the same level as your chest, touch the floor for a little extra challenge, and then do the same to the other side. When you're back in your original position after doing both sides it will count as 1 rep."),
        "builtin.medicine-ball-twist": ExerciseContentSource(title: "Medicine ball twist", url: "https://wger.de/api/v2/exerciseinfo/1089/", author: "clafal", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "In a seated position, the torso is rotated from side to side without forcing, approaching the knees and making the ball touch the ground from time to time"),
        "builtin.bicycle-crunch": ExerciseContentSource(title: "bicycle crunches", url: "https://wger.de/api/v2/exerciseinfo/1412/", author: "hpmbala@gmail.com", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "Bicycle crunches are a core exercise performed on the floor. Lie on your back with your hands behind your head and legs extended. Lift your shoulders off the ground, bring one knee toward your chest, and twist your torso so your opposite elbow meets the knee. Alternate sides in a pedaling motion, ensuring controlled movements and engaging your core throughout the exercise."),
        "builtin.side-crunch": ExerciseContentSource(title: "Side Crunch", url: "https://wger.de/api/v2/exerciseinfo/576/", author: "kwrindy", licenseName: "CC-BY-SA 3", licenseURL: "https://creativecommons.org/licenses/by-sa/3.0/deed.en", originalDescription: "Hold weight in one hand. Bend side ways to the knee. Pull upo to upright position using your obliquus."),
        "builtin.incline-crunch": ExerciseContentSource(title: "Incline Crunches", url: "https://wger.de/api/v2/exerciseinfo/171/", author: "wger.de", licenseName: "CC-BY-SA 3", licenseURL: "https://creativecommons.org/licenses/by-sa/3.0/deed.en", originalDescription: "Lay down on your back on a inclined bench, feet are on one end of the bench. Ask a partner or use some other help (barbell, etc.) to keep them fixed, your hands are behind your head. From this position move your upper body up till your head or elbows touch your knees. Do this movement by rolling up your back."),
        "builtin.cable-crunch": ExerciseContentSource(title: "Crunches With Cable", url: "https://wger.de/api/v2/exerciseinfo/173/", author: "wger.de", licenseName: "CC-BY-SA 3", licenseURL: "https://creativecommons.org/licenses/by-sa/3.0/deed.en", originalDescription: "Take the cable on your hands and hold it next to your temples. Knee down and hold your upper body straight and bend forward. Go down with a fast movement, rolling your back in (your ellbows point to your knees). Once down, go slowly back to the initial position."),
        "builtin.machine-crunch": ExerciseContentSource(title: "Crunches on Machine", url: "https://wger.de/api/v2/exerciseinfo/172/", author: "wger.de", licenseName: "CC-BY-SA 3", licenseURL: "https://creativecommons.org/licenses/by-sa/3.0/deed.en", originalDescription: "The procedure is very similar as for regular crunches, only with the additional weight of the machine. Sit on the machine, put both feet firmly on the ground. Grab the to the weights, cables, etc. and do a rolling motion forwards (the spine should ideally lose touch vertebra by vertebra). Slowly return to the starting position."),
        "builtin.swiss-ball-crunch": ExerciseContentSource(title: "Ball crunches", url: "https://wger.de/api/v2/exerciseinfo/165/", author: "Konsumopfer", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: ""),
        "builtin.lying-leg-raise": ExerciseContentSource(title: "Leg Raises, Lying", url: "https://wger.de/api/v2/exerciseinfo/377/", author: "wger.de", licenseName: "CC-BY-SA 3", licenseURL: "https://creativecommons.org/licenses/by-sa/3.0/deed.en", originalDescription: "Lay down on a bench and hold onto the recliner with your hands to keep you stable. Hold your legs straight and lift them till they make an angle of about 45°. Make a short pause of 1 sec. and go slowly down to the initial position. To increase the intensity you can make a longer pause of 7 sec. every 5th time."),
        "builtin.hanging-leg-raise": ExerciseContentSource(title: "Hanging Leg Raises", url: "https://wger.de/api/v2/exerciseinfo/283/", author: "robhoyt", licenseName: "CC-BY-SA 3", licenseURL: "https://creativecommons.org/licenses/by-sa/3.0/deed.en", originalDescription: "Hanging from bar or straps, bring legs up with knees extended or flexed"),
        "builtin.seated-knee-tuck": ExerciseContentSource(title: "Seated Knee Tuck", url: "https://wger.de/api/v2/exerciseinfo/1105/", author: "utkb", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "Sit on floor or mat. Place arms slightly behind you. Raise legs. Now extend your legs and pull them back."),
        "builtin.dumbbell-side-bend": ExerciseContentSource(title: "Dumbbell Side Bend", url: "https://wger.de/api/v2/exerciseinfo/1650/", author: "AlucardEvil40", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "This exercise involves holding a dumbbell in one hand and bending sideways to work the oblique muscles on the side of the body. It can be done standing or seated and is often used as a core strengthening exercise."),
        "builtin.decline-push-up": ExerciseContentSource(title: "Push-Ups | Decline", url: "https://wger.de/api/v2/exerciseinfo/1112/", author: "anon1337", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "Decline push-ups are another modified version of the traditional push-up that target the upper body muscles in a different way. To perform a decline push-up, elevate your feet on an elevated surface, such as a bench, chair, or step, while placing your hands on the ground in a push-up position. Lower your body towards the ground while maintaining a straight line from your shoulders to your ankles, and then push back up to the starting position.\nUnlike the inclined push-up, the decline push-up places more emphasis on the shoulders and triceps, while still engaging the chest muscles to a lesser extent. By elevating your feet, you increase the difficulty of the exercise by placing more weight on your upper body, forcing your shoulders and triceps to work harder to push your body back up. The decline push-up can be a great way to challenge your upper body strength and improve your ability to perform other push-up variations. As with any exercise, be sure to use proper form and start with a height that is appropriate for your strength and fitness level."),
        "builtin.pike-push-up": ExerciseContentSource(title: "Pike Push Ups", url: "https://wger.de/api/v2/exerciseinfo/454/", author: "Nash", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "Push Up performed from a pike position (optional to have feet elevated)."),
        "builtin.parallette-push-up": ExerciseContentSource(title: "Push-Ups | Parallettes", url: "https://wger.de/api/v2/exerciseinfo/1113/", author: "anon1337", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "Parallettes push-ups are a variation of the traditional push-up that are performed with the hands on parallel bars, known as parallettes. To perform a parallettes push-up, assume a push-up position with your hands on the parallettes and your feet on the ground. Lower your body towards the ground while keeping your elbows close to your sides, and then push back up to the starting position.\nParallettes push-ups place more emphasis on the chest and shoulders compared to traditional push-ups, as they allow for a greater range of motion in the shoulder joint. This increased range of motion can also help to improve shoulder stability and mobility. Additionally, parallettes push-ups engage the core muscles more than traditional push-ups, as the instability of the parallettes requires greater activation of the core muscles to maintain proper form.\nThe added challenge of balancing on the parallettes also requires greater upper body strength and control, making parallettes push-ups a more advanced variation of the traditional push-up. They can be a great way to challenge yourself and add variety to your upper body workout routine. As always, be sure to use proper form and start with a level that is appropriate for your strength and fitness level."),
        "builtin.rotational-push-up": ExerciseContentSource(title: "Push-up rotations", url: "https://wger.de/api/v2/exerciseinfo/985/", author: "Upstream contributor not specified", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "Starting position:\n\nGet into the starting push-up position, with your hands and toes touching the ground and back, arms and legs straight. To get to this position, you can lie down on your stomach, place your hands facing down next to your head, and lifting your arms up until they are straight.\n\nSteps:\n\n1. Perform a standard push-up:\n\n1.a Bend arms until chest almost touches the ground, making sure the back is straight.1.b Use your arms to lift yourself back up to starting position.\n\n2. Rotate your body to the side so that the back is straight, the bottom hand supporting the body is fully extended, and only the bottom hand and foot touch the floor.\n3. Repeat, changing sides at step 2 each time."),
        "builtin.bear-crawl": ExerciseContentSource(title: "Bear Walk 2", url: "https://wger.de/api/v2/exerciseinfo/57/", author: "nate303303", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "-Rest your weight on your palms and the balls of your feet, not dissimilar to normal pushup position\n\n-Move by stepping with your R palm and L foot, then your L palm and R foot.  Basically, walk like a lumbering bear.\n\n-Move as fast as you can.  Measure your reps/sets in either distance (i.e. 40 yards) or time (i.e. 45 seconds)\n\n-Works your Pecs, Deltoids, Triceps, Traps, Lats, Abs and Lower Back, Hip Flexors, Quads, Glutes and Calves"),
        "builtin.dumbbell-farmer-carry": ExerciseContentSource(title: "Dumbbell farmer's carry", url: "https://wger.de/api/v2/exerciseinfo/1116/", author: "philip", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "Grab half your body weight in each hand and walk."),
        "builtin.interval-running": ExerciseContentSource(title: "Run - Interval Training", url: "https://wger.de/api/v2/exerciseinfo/529/", author: "BeLikeWater", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "Run and do some interval trainings such as hill repat, fartlek,.."),
        "builtin.treadmill-running": ExerciseContentSource(title: "Run - Treadmill", url: "https://wger.de/api/v2/exerciseinfo/530/", author: "foguinho.peruca", licenseName: "CC-BY-SA 3", licenseURL: "https://creativecommons.org/licenses/by-sa/3.0/deed.en", originalDescription: "Run on a treadmill"),
        "builtin.jump-rope": ExerciseContentSource(title: "Jump rope: basic jumps", url: "https://wger.de/api/v2/exerciseinfo/993/", author: "Upstream contributor not specified", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "Starting position:\n\nPut your feet close together, bend the knees a bit, keep your head and body straight, keep elbows in, open your arms.\n\nSteps:\n\n1. Spin only your wrists with enough force to make the rope spin.\n2. Jump just high enough to pass the rope below your feet.\n3. Repeat.\n\nNotes:\n\nThis exercise requires a jump rope. Make sure the rope length is adjusted to your height. One way to check is to grab both handles with one hand and stand on the middle of the rope hanging on the ground with one foot. If the rope (excluding the handles) reaches just below your chest, its length is right. A shorter rope would be hazardous, as you might hit yourself, and a longer rope would make for bad form."),
        "builtin.jumping-jack": ExerciseContentSource(title: "Jumping Jacks", url: "https://wger.de/api/v2/exerciseinfo/320/", author: "student1234", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "A jumping jack or star jump, also called side-straddle hop in the US military, is a physical jumping exercise performed by jumping to a position with the legs spread wide and the hands going overhead, sometimes in a clap, and then returning to a position with the feet together and the arms at the sides"),
        "builtin.high-knees": ExerciseContentSource(title: "High knees", url: "https://wger.de/api/v2/exerciseinfo/983/", author: "Upstream contributor not specified", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "Starting positionStand straight.\n\nSteps:\n\n1. Run in place, putting knees as high up as is comfortable and switching legs at a quick pace."),
        "builtin.butt-kicks": ExerciseContentSource(title: "Talons fesses", url: "https://wger.de/api/v2/exerciseinfo/1285/", author: "painDpice", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "Touch your heels to your buttocks, while remaining static or moving"),
        "builtin.punching-bag": ExerciseContentSource(title: "Bag training", url: "https://wger.de/api/v2/exerciseinfo/1092/", author: "clafal", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "Bag training improves muscle definition of: deltoids; rear deltoids; triceps; biceps, as well as being a great cardio exercise"),
        "builtin.recumbent-bike": ExerciseContentSource(title: "Recumbent Bike", url: "https://wger.de/api/v2/exerciseinfo/1376/", author: "pera_perkan", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "For this exercise Recumbent Bike is needed. You just sit on it, set level and time and start the workout"),
        "builtin.stair-climber": ExerciseContentSource(title: "ClimbMill", url: "https://wger.de/api/v2/exerciseinfo/1449/", author: "hpmbala@gmail.com", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "The ClimbMill, also known as a stair climber, is a cardio-focused machine that simulates climbing stairs. It provides an effective way to improve endurance while strengthening the lower body. To use the machine, step onto the moving stairs, maintain an upright posture, and use the handrails for balance if needed. Adjust the speed and intensity to match your fitness level. This exercise helps improve cardiovascular health, burns calories, and enhances lower body muscle endurance."),
        "builtin.ski-ergometer": ExerciseContentSource(title: "Ski Machine", url: "https://wger.de/api/v2/exerciseinfo/1526/", author: "flanny", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "1. Start standing on the platform with your feet hip-width apart.\n2. Reach overhead to grip the handles with your palms facing in.\n3. Soften your knees, then simultaneously drive your butt back as if you're closing a door behind you while pulling your arms straight down past your hips until your hands pass by the side of your knees.\n4. Next, bring your arms back overhead while thrusting your hips forward until you're standing with your arms fully extended.\n5. Repeat for reps, time or distance."),
        "builtin.battle-rope": ExerciseContentSource(title: "Battle Ropes", url: "https://wger.de/api/v2/exerciseinfo/1524/", author: "flanny", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "1. Hold the ends of the rope at arm's length in front of your hips with your hands shoulder-width apart.\n2. Brace your core and begin alternately raising and lowering each arm explosively.\n3. Keep alternating arms for three to four sets of 1 to 2 minutes."),
        "builtin.sled-push": ExerciseContentSource(title: "Sled Push", url: "https://wger.de/api/v2/exerciseinfo/1523/", author: "flanny", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "1. Load the sled with 25% of your maximum load. If you don’t know this, choose a weight you can push for 10 minutes with short breaks. Beginners may choose to push the sled with no weight.\n2. Stand behind the sled and grab the poles with a high-grip hand position.\n3. Engage your core muscles and start pushing the sled forward as fast as you can, powering through your entire leg. Extend your hips and knees as you move the sled forward. Your foot stance should resemble your natural running position."),
        "builtin.medicine-ball-slam": ExerciseContentSource(title: "Ball Slams", url: "https://wger.de/api/v2/exerciseinfo/1525/", author: "flanny", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "1. Stand with your feet about shoulder-width apart, your knees and hips slightly bent, holding the ball in both hands at chest height. Engage your core, and keep a good posture.\n2. Extend your knees and drive your hips forward while simultaneously lifting the ball. Aim for being as tall as possible, the ball overhead, arms up, hips slightly forward, and on your toes from the force of your drive.\n3. Use your core and arms to slam the medicine ball straight down between your feet with as much force as possible. Press your hips back and bend your knees to further power the slam. Exhale as you slam the ball down.\n4. Squat down to pick up the ball from the floor, then immediately move into the next slam by repeating the movement. Repeat for reps or time."),
        "builtin.march-in-place": ExerciseContentSource(title: "March or jog in place", url: "https://wger.de/api/v2/exerciseinfo/1584/", author: "MrAlfaRobot", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "Low-impact cardiovascular exercise that simulates running without moving, ideal for warming up, improving endurance, or training in small spaces."),
        "builtin.step-jack": ExerciseContentSource(title: "Step Jack", url: "https://wger.de/api/v2/exerciseinfo/1962/", author: "Anon#2", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "The Step Jack is a low-impact plyometric-style move that provides cardiovascular benefits without the joint stress of jumping. It works the entire body, specifically targeting the legs, core, and shoulders. This move is ideal for beginners, individuals with joint sensitivities, or as a dynamic warm-up to gradually elevate the heart rate.\nNotes (Instructions):\n1. ​Stand upright with your feet together and arms at your sides.\n2. ​Step your right foot out to the side while simultaneously swinging both arms up above your head.\n3. Bring your right foot back to the center and lower your arms.\n4. ​Immediately repeat the movement, stepping out with your left foot.\n5. ​Continue alternating sides at a steady, rhythmic pace."),
        "builtin.freestyle-swimming": ExerciseContentSource(title: "Easy Continuous Swim (Freestyle)", url: "https://wger.de/api/v2/exerciseinfo/2480/", author: "Imported from swim plan", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "Swim freestyle at a relaxed, steady pace without stopping — think conversation pace, not racing. Focus on smooth, even strokes rather than speed or breathing technique; this is just to get your body moving and your heart rate up."),
        "builtin.kickboard-swimming": ExerciseContentSource(title: "Kick with Board", url: "https://wger.de/api/v2/exerciseinfo/2481/", author: "Imported from swim plan", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "Hold a kickboard with both hands, arms extended in front of you, face in the water (lift head forward to breathe when needed). Kick from your hips, not your knees, keeping your legs mostly straight with a slight bend and a steady, compact flutter kick. This builds leg endurance and keeps your body horizontal without needing to worry about your arms."),
        "builtin.boxing": ExerciseContentSource(title: "Boxing", url: "https://wger.de/api/v2/exerciseinfo/2542/", author: "SAH", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "Bag workout for boxing skill development and cardio improvement"),
        "builtin.standing-calf-stretch": ExerciseContentSource(title: "Standing Calf Stretch", url: "https://wger.de/api/v2/exerciseinfo/1239/", author: "erikocobra", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "This stretch targets the gastrocnemius (the chief muscle of the calf of the leg, which flexes the knee and foot). It is easy to perform anywhere. All you need is a wall or a chair."),
        "builtin.seated-calf-stretch": ExerciseContentSource(title: "Sitting Calf Stretch (Dorsiflexion)", url: "https://wger.de/api/v2/exerciseinfo/1274/", author: "erikocobra", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "This is a light stretch for the calf that is great for rehab."),
        "builtin.hip-flexor-stretch": ExerciseContentSource(title: "Hip Flexor Stretch", url: "https://wger.de/api/v2/exerciseinfo/1867/", author: "Davidgj32", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "Kneel in a lunge position with one knee on the floor and the other foot in front, hands on your hips.\n\nKeep your torso upright, squeeze the glute of the back leg and push your hips forward until you feel a stretch at the front of the hip and thigh. Hold, then switch sides."),
        "builtin.figure-four-stretch": ExerciseContentSource(title: "Lying Figure Four Stretch", url: "https://wger.de/api/v2/exerciseinfo/1869/", author: "Davidgj32", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "View the video to undestand the exercise"),
        "builtin.band-hamstring-stretch": ExerciseContentSource(title: "Lying Hamstring Stretch with Band", url: "https://wger.de/api/v2/exerciseinfo/1870/", author: "Davidgj32", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "View the video to undestand the exercise"),
        "builtin.quadriceps-stretch": ExerciseContentSource(title: "Quad Stretch", url: "https://wger.de/api/v2/exerciseinfo/1873/", author: "Davidgj32", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "View the video to undestand the exercise"),
        "builtin.lunge-twist-stretch": ExerciseContentSource(title: "Lunge with Twist Stretch", url: "https://wger.de/api/v2/exerciseinfo/1868/", author: "Davidgj32", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "View the video to undestand the exercise"),
        "builtin.ankle-dorsiflexion-rock": ExerciseContentSource(title: "ankle dorsiflexion rocks", url: "https://wger.de/api/v2/exerciseinfo/1804/", author: "Davidgj32", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "Move your knee forward, keeping your heel on the ground. Hold the position for a couple of seconds and return to the starting position."),
        "builtin.hip-circle": ExerciseContentSource(title: "Hip Circles", url: "https://wger.de/api/v2/exerciseinfo/1862/", author: "Davidgj32", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "View the video to undestand the exercise"),
        "builtin.band-ankle-mobility": ExerciseContentSource(title: "Banded Ankle Mobility", url: "https://wger.de/api/v2/exerciseinfo/1865/", author: "Davidgj32", licenseName: "CC-BY-SA 4", licenseURL: "https://creativecommons.org/licenses/by-sa/4.0/deed.en", originalDescription: "Anchor a resistance band low behind you, for example at the bottom of a rack, and loop it around the front of your ankle, just above the foot.\n\nGet into a half-kneeling position with the banded foot in front, so that the band pulls your ankle backwards.\n\nKeeping your heel on the floor, drive your knee forward over your toes, then return under control. Repeat for several reps and switch sides."),
